Sale register(String key, Sale sale) {
    if (!store.insertIfAbsent(key)) {   // UNIQUE constraint decides the race
        return store.response(key);
    }
    Sale saved = sales.register(sale);  // a second, separate transaction
    store.saveResponse(key, saved);
    return saved;
}

